export async function loadInfractions(): Promise<Infraction[]> {
  // A falha ao descompactar o catálogo principal não deve ocultar as infrações
  // adicionais cadastradas em código.
  let existing: Infraction[] = [];
  try {
    const binary = atob(compressedInfractions);
    const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0));
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
    existing = (await new Response(stream).json()) as Infraction[];
  } catch (error) {
    console.warn("Não foi possível carregar o catálogo compactado de infrações; usando os registros adicionais.", error);
  }

  // Consolida pelo código para que registros já existentes não apareçam em duplicidade.
  const merged = [...existing, ...additionalInfractions];
  const unique = new Map<string, Infraction>();
  for (const infraction of merged) {
    const key = infraction.code.trim();
    if (!unique.has(key)) unique.set(key, infraction);
  }
  return [...unique.values()];
}
